function isString(value: unknown): value is string {
  return typeof value === 'string';
}

function printLength(value: unknown) {
  if (isString(value)) {
    // value is now string in this branch
    console.log(value.length);
  }
}

type SuccessResponse<
  T
> = { status: 'success'; data: T };

type ErrorResponse = { status: 'error'; message: string };

type ApiResponse<T> = SuccessResponse<T> | ErrorResponse;

function isSuccess<T>(
  response: ApiResponse<T>
): response is SuccessResponse<T> {
  return response.status === 'success';
}

function useUser(userId: string) {
  const response = fetch(`/api/users/${userId}`);
  if (isSuccess(response)) {
    // response is SuccessResponse<User> here
    console.log(response.data.name);
  } else {
    console.error(response.message);
  }
}

interface ClickPayload {
  x: number;
  y: number;
  target: HTMLElement;
}

function isClickPayload(
  payload: unknown
): payload is ClickPayload {
  return (
    typeof payload === 'object' &&
    payload !== null &&
    'x' in payload &&
    'y' in payload &&
    'target' in payload
  );
}

function handleCustomEvent(payload: unknown) {
  if (isClickPayload(payload)) {
    console.log(`Clicked at ${payload.x}, ${payload.y}`);
  }
}
